const int N = 101;
​
int main() {
    // 记录 发送者 -> 接收者 的短信数量
    vector<vector<int>> ans(N, vector<int>(N,0));
    map<int, set<int>> mp;
    int n;
    cin >>n;
    for (int i = 0; i < n; i++) {
        int idx1,idx2;
        cin>>idx1>>idx2;
        ans[idx1][idx2]++;
        mp[idx1].insert(idx2);
    }

    int id;
    cin >> id;
    bool flag = false;
    int l = 0;
    int m = 0;

    set<int> s = mp[id];
    // 发送数量
    int sendCount = 0;
    // 接受数量
    int receiveCount = 0;
    if (!s.empty()) {
        for (int x : s) {
            sendCount += ans[id][x];
            if (mp[x].find(id) == mp[x].end()) {
                l++;
            } else {
                if (ans[id][x] - ans[x][id] > 5) {
                    flag = true;
                }
            }
        }
    }
​
    // 统计接受短信数量 
    for (auto p : mp) {
        if (p.first == id) {
            continue;
        }
        set<int> tmp = p.second;
        if (tmp.find(id) != tmp.end()) {
            receiveCount += ans[p.first][id];
        }
    }

    if (l > 5) {
        flag = true;
    }
​
    if (sendCount - receiveCount > 10) {
        flag = true;
    }
​
    string str = flag ? "true" : "false";
​
