public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = 101;
        int[][] ans = new int[N][N]; // 记录发送者 -> 接收者的短信数量
        Map<Integer, Set<Integer>> mp = new HashMap<>();
​
        int n = sc.nextInt(); // 读取条目数
        for (int i = 0; i < n; i++) {
            int idx1 = sc.nextInt(), idx2 = sc.nextInt();
            ans[idx1][idx2]++;
            mp.computeIfAbsent(idx1, k -> new HashSet<>()).add(idx2);
        }
​
        int id = sc.nextInt();
        boolean flag = false;
        int l = 0;
        // 发送数量 接受数量
        int sendCount = 0, receiveCount = 0;
​
        Set<Integer> s = mp.getOrDefault(id, new HashSet<>());
        if (!s.isEmpty()) {
            for (int x : s) {
                sendCount += ans[id][x];
                if (!mp.containsKey(x) || !mp.get(x).contains(id)) {
                    l++;
                } else {
                    if (ans[id][x] - ans[x][id] > 5) {
                        flag = true;
                    }
                }
            }
        }
        // 统计接收数量
        for (Map.Entry<Integer, Set<Integer>> entry : mp.entrySet()) {
            int sender = entry.getKey();
            if (sender == id) continue;
            if (entry.getValue().contains(id)) {
                receiveCount += ans[sender][id];
            }
        }
        // 判断是否是垃圾信息
        if (l > 5) flag = true;
        if (sendCount - receiveCount > 10) flag = true;
​
        System.out.println(flag + " " + l + " " + (sendCount - receiveCount));
        sc.close();
    }
}
