package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
const N = 101
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text())
​
    ans := make([][]int, N)
    for i := range ans {
        ans[i] = make([]int, N)
    }
​
    mp := make(map[int]map[int]struct{})
​
    for i := 0; i < n; i++ {
        scanner.Scan()
        parts := strings.Fields(scanner.Text())
        idx1, _ := strconv.Atoi(parts[0])
        idx2, _ := strconv.Atoi(parts[1])
​
        ans[idx1][idx2]++
​
        if mp[idx1] == nil {
            mp[idx1] = make(map[int]struct{})
        }
        mp[idx1][idx2] = struct{}{}
    }
​
    scanner.Scan()
    id, _ := strconv.Atoi(scanner.Text())
​
    flag := false
    l := 0
​
    // 发送数量 接受数量
    sendCount := 0
    receiveCount := 0
​
    s, exists := mp[id]
    if exists {
        for x := range s {
            sendCount += ans[id][x]
            if _, found := mp[x][id]; !found {
                l++
            } else if ans[id][x]-ans[x][id] > 5 {
                flag = true
            }
        }
    }
     // 统计接收数量
    for sender, receivers := range mp {
        if sender == id {
            continue
        }
        if _, found := receivers[id]; found {
            receiveCount += ans[sender][id]
        }
    }
​
    if l > 5 {
        flag = true
    }
    if sendCount-receiveCount > 10 {
        flag = true
    }
​
    fmt.Printf("%t %d %d\n", flag, l, sendCount-receiveCount)
}
